import{_ as e,c as i,o as n,j as s,Y as o,t as r}from"./chunks/framework.D-NV0Bun.js";const k=JSON.parse('{"title":"git-check-mailmap | x-cmd man (git man1) | Show canonical names and email addresses of contacts","titleTemplate":false,"description":"x-cmd man (git man1 Manual Page) | git-check-mailmap - Show canonical names and email addresses of contacts","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"git-check-mailmap | x-cmd man (git man1) | Show canonical names and email addresses of contacts"}],["meta",{"name":"og:description","content":"x-cmd man (git man1 Manual Page) | git-check-mailmap - Show canonical names and email addresses of contacts"}]]},"headers":[],"params":{"isMan":true,"man":"git-check-mailmap","category":"git man1","desc":"Show canonical names and email addresses of contacts"},"relativePath":"git/man1/git-check-mailmap.md","filePath":"git/man1/[man].md"}'),l={name:"git/man1/git-check-mailmap.md"},c={class:"visually-hidden"};function h(t,a,m,d,p,g){return n(),i("div",null,[s("h1",c,r(t.$params.man),1),a[0]||(a[0]=o('<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>git-check-mailmap - Show canonical names and email addresses of contacts</p><h2 id="synopsis" tabindex="-1">SYNOPSIS <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;SYNOPSIS&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check-mailmap</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [&lt;options&gt;] </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">contact</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">...</span></span></code></pre></div><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>For each &quot;Name &lt;user@host&gt;&quot; or &quot;&lt;user@host&gt;&quot; from the command-line or standard input (when using <strong>--stdin</strong>), look up the person&#39;s canonical name and email address (see &quot;Mapping Authors&quot; below). If found, print them; otherwise print the input as-is.</p><h2 id="options" tabindex="-1">OPTIONS <a class="header-anchor" href="#options" aria-label="Permalink to &quot;OPTIONS&quot;">​</a></h2><p>--stdin</p><blockquote><p>Read contacts, one per line, from the standard input after exhausting contacts provided on the command-line.</p></blockquote><h2 id="output" tabindex="-1">OUTPUT <a class="header-anchor" href="#output" aria-label="Permalink to &quot;OUTPUT&quot;">​</a></h2><p>For each contact, a single line is output, terminated by a newline. If the name is provided or known to the <em>mailmap</em>, &quot;Name &lt;user@host&gt;&quot; is printed; otherwise only &quot;&lt;user@host&gt;&quot; is printed.</p><h2 id="configuration" tabindex="-1">CONFIGURATION <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;CONFIGURATION&quot;">​</a></h2><p>See <strong>mailmap.file</strong> and <strong>mailmap.blob</strong> in <strong>git-config</strong>(1) for how to specify a custom <strong>.mailmap</strong> target file or object.</p><h2 id="mapping-authors" tabindex="-1">MAPPING AUTHORS <a class="header-anchor" href="#mapping-authors" aria-label="Permalink to &quot;MAPPING AUTHORS&quot;">​</a></h2><p>See <strong>gitmailmap</strong>(5).</p><h2 id="git" tabindex="-1">GIT <a class="header-anchor" href="#git" aria-label="Permalink to &quot;GIT&quot;">​</a></h2><p>Part of the <strong>git</strong>(1) suite</p>',17))])}const f=e(l,[["render",h]]);export{k as __pageData,f as default};
